1	/* ============================================================
2	   tierlist.js — 英雄梯度排行榜核心引擎
3	   支持 LOLM（分路/Z-score） 和 曙光英雄（无分路/加权和）
4	   ============================================================ */
5	
6	"use strict";
7	
8	// ---- 全局状态 ----
9	let gameConfig = null;      // 当前游戏的 config.json
10	let gameData = null;        // 计算后的结构化数据
11	let currentMethod = "zscore"; // LOLM: "zscore"|"simple", SG: "weighted"
12	let currentView = "lane";   // "lane"|"global"
13	let currentLane = null;     // 当前分路名（仅 hasLanes）
14	
15	// ---- 工具函数 ----
16	function parsePct(s) {
17	  if (typeof s === "number") return s / 100;
18	  return parseFloat(String(s).replace("%", "")) / 100;
19	}
20	
21	function mean(arr) {
22	  return arr.reduce((a, b) => a + b, 0) / arr.length;
23	}
24	
25	function stdDev(arr) {
26	  const m = mean(arr);
27	  const v = arr.reduce((s, v) => s + (v - m) ** 2, 0) / arr.length;
28	  return Math.sqrt(v) || 1;
29	}
30	
31	function zScores(arr) {
32	  const m = mean(arr);
33	  const s = stdDev(arr);
34	  if (s === 0) return arr.map(() => 0);
35	  return arr.map(v => (v - m) / s);
36	}
37	
38	function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }
39	
40	function getRankClass(rank) {
41	  if (rank === 1) return "rank-1";
42	  if (rank === 2) return "rank-2";
43	  if (rank === 3) return "rank-3";
44	  return "";
45	}
46	
47	function getWrClass(val) {
48	  if (val >= 0.52) return "wr-high";
49	  if (val >= 0.49) return "wr-mid";
50	  return "wr-low";
51	}
52	
53	function getCwClass(val) {
54	  // 战力分：高(>140) 中(80-140) 低(<80)
55	  if (val >= 140) return "cw-high";
56	  if (val >= 80) return "cw-mid";
57	  return "cw-low";
58	}
59	
60	// ---- 梯度系统 ----
61	function getTierColors() {
62	  return gameConfig.tiers.colors;
63	}
64	
65	function getTierThresholds() {
66	  return gameConfig.tiers.thresholds;
67	}
68	
69	function getTierBadge(tier) {
70	  const color = getTierColors()[tier] || "#8c8c8c";
71	  return `<span class="tier-badge" style="background:${color}">${tier}</span>`;
72	}
73	
74	function getScoreBar(score, tier) {
75	  const color = getTierColors()[tier] || "#8c8c8c";
76	  return `<div class="score-bar-wrap">
77	    <div class="score-bar"><div class="score-bar-fill" style="width:${score}%;background:${color}"></div></div>
78	    <span class="score-value">${score.toFixed(1)}</span></div>`;
79	}
80	
81	function assignTiers(heroes, scoreKey) {
82	  const sorted = [...heroes].sort((a, b) => b[scoreKey] - a[scoreKey]);
83	  const n = sorted.length;
84	  const thresholds = getTierThresholds();
85	  sorted.forEach((h, rank) => {
86	    const pct = 1 - rank / n;
87	    let tier = "T4";
88	    for (const t of thresholds) {
89	      if (pct >= t.pct) { tier = t.tier; break; }
90	    }
91	    h.tier = tier;
92	    h.rank = rank + 1;
93	  });
94	}
95	
96	// ============================================================
97	// LOLM 算法
98	// ============================================================
99	function computeLOLM(rawData) {
100	  const hasLanes = gameConfig.hasLanes;
101	  const lanes = {};
102	  const allHeroes = [];
103	
104	  for (const laneCfg of gameConfig.lanes) {
105	    const raw = rawData[laneCfg.name];
106	    if (!raw) continue;
107	    const heroes = raw.map(h => ({
108	      name: h.heroName,
109	      lane: laneCfg.name,
110	      headIcon: gameConfig.headIconPath ? (gameConfig.gameId + "/" + gameConfig.headIconPath.replace("{name}", h.heroName)) : null,
111	      wr: parsePct(h.winRate),
112	      pr: parsePct(h.pickRate),
113	      br: parsePct(h.banRate),
114	      bp: parsePct(h.pickRate) + parsePct(h.banRate)
115	    }));
116	    lanes[laneCfg.name] = heroes;
117	    allHeroes.push(...heroes);
118	  }
119	
120	  // Z-score 加权（分路内计算 Z-score）
121	  for (const [laneName, heroes] of Object.entries(lanes)) {
122	    const zWr = zScores(heroes.map(h => h.wr));
123	    const zPr = zScores(heroes.map(h => h.pr));
124	    const zBr = zScores(heroes.map(h => h.br));
125	    heroes.forEach((h, i) => {
126	      h.z_wr = zWr[i]; h.z_pr = zPr[i]; h.z_br = zBr[i];
127	      h.raw_zscore = 0.5 * zWr[i] + 1.0 * zPr[i] + 3.0 * zBr[i];
128	    });
129	  }
130	
131	  // 简易公式
132	  for (const [laneName, heroes] of Object.entries(lanes)) {
133	    heroes.forEach(h => {
134	      h.raw_simple = Math.pow(h.wr, 0.3) * (h.pr + 2.5 * h.br) * 100;
135	    });
136	  }
137	
138	  // 分路内 min-max 归一化
139	  function normalize(heroes, rawKey, normKey) {
140	    const vals = heroes.map(h => h[rawKey]);
141	    const lo = Math.min(...vals), hi = Math.max(...vals);
142	    const rng = hi - lo || 1;
143	    heroes.forEach(h => { h[normKey] = ((h[rawKey] - lo) / rng) * 100; });
144	  }
145	
146	  for (const [, heroes] of Object.entries(lanes)) {
147	    normalize(heroes, "raw_zscore", "score_zscore");
148	    normalize(heroes, "raw_simple", "score_simple");
149	  }
150	
151	  // 全局归一化
152	  normalize(allHeroes, "raw_zscore", "score_zscore_global");
153	  normalize(allHeroes, "raw_simple", "score_simple_global");
154	
155	  // 分配梯度
156	  for (const [, heroes] of Object.entries(lanes)) {
157	    assignTiersWithKey(heroes, "score_zscore", "tier_zscore");
158	    assignTiersWithKey(heroes, "score_simple", "tier_simple");
159	    assignTiersWithKey(heroes, "score_zscore_global", "tier_global");
160	  }
161	
162	  function assignTiersWithKey(heroes, scoreKey, tierKey) {
163	    const sorted = [...heroes].sort((a, b) => b[scoreKey] - a[scoreKey]);
164	    const n = sorted.length;
165	    const thresholds = getTierThresholds();
166	    sorted.forEach((h, i) => {
167	      const pct = 1 - i / n;
168	      let tier = "T4";
169	      for (const t of thresholds) {
170	        if (pct >= t.pct) { tier = t.tier; break; }
171	      }
172	      h[tierKey] = tier;
173	      // Store lane rank under a consistent key: _rank_zscore / _rank_simple
174	      if (tierKey === "tier_zscore") h._rank_zscore = i + 1;
175	      if (tierKey === "tier_simple") h._rank_simple = i + 1;
176	    });
177	  }
178	
179	  // 全局排名
180	  const globalZ = [...allHeroes].sort((a, b) => b.score_zscore_global - a.score_zscore_global);
181	  globalZ.forEach((h, i) => { h.global_rank_zscore = i + 1; });
182	  const globalSimple = [...allHeroes].sort((a, b) => b.score_simple_global - a.score_simple_global);
183	  globalSimple.forEach((h, i) => { h.global_rank_simple = i + 1; });
184	
185	  return { lanes, allHeroes, globalZ, globalSimple };
186	}
187	
188	// ============================================================
189	// 曙光英雄算法（从 Python validate_pure.py 移植）
190	// ============================================================
191	function computeSG(rawData) {
192	  const heroes = rawData.map(h => ({
193	    name: h.heroName,
194	    headIcon: gameConfig.headIconPath ? ("曙光英雄/" + gameConfig.headIconPath.replace("{name}", h.heroName)) : null,
195	    appearanceRank: parseInt(h.appearanceRank),
196	    combatPower: parseFloat(h.combatPower),
197	    winRate: parseFloat(String(h.winRate).replace("%", "")) / 100,
198	    lane: null
199	  }));
200	
201	  const N = heroes.length;
202	  const weights = gameConfig.algorithm.weights;
203	
204	  // 出场分：rank 越小越好，转换为 1 → 1.0, N → 0.0
205	  const appearanceScores = heroes.map(h => 1 - (h.appearanceRank - 1) / (N - 1));
206	
207	  // 战力分 min-max 归一化
208	  const combatVals = heroes.map(h => h.combatPower);
209	  const combatMin = Math.min(...combatVals), combatMax = Math.max(...combatVals);
210	  const combatRange = combatMax - combatMin || 1;
211	  const combatScores = combatVals.map(v => (v - combatMin) / combatRange);
212	
213	  // 胜率 min-max 归一化
214	  const wrVals = heroes.map(h => h.winRate);
215	  const wrMin = Math.min(...wrVals), wrMax = Math.max(...wrVals);
216	  const wrRange = wrMax - wrMin || 1;
217	  const wrScores = wrVals.map(v => (v - wrMin) / wrRange);
218	
219	  // 加权和
220	  heroes.forEach((h, i) => {
221	    h.raw_weighted = weights.appearance * appearanceScores[i]
222	                   + weights.combat * combatScores[i]
223	                   + weights.winrate * wrScores[i];
224	  });
225	
226	  // 最终 min-max 归一化 → 0~100
227	  const rawVals = heroes.map(h => h.raw_weighted);
228	  const rawMin = Math.min(...rawVals), rawMax = Math.max(...rawVals);
229	  const rawRange = rawMax - rawMin || 1;
230	  heroes.forEach(h => { h.score = ((h.raw_weighted - rawMin) / rawRange) * 100; });
231	
232	  // 分配梯度
233	  const sorted = [...heroes].sort((a, b) => b.score - a.score);
234	  const thresholds = getTierThresholds();
235	  sorted.forEach((h, i) => {
236	    const pct = 1 - i / N;
237	    let tier = "T4";
238	    for (const t of thresholds) {
239	      if (pct >= t.pct) { tier = t.tier; break; }
240	    }
241	    h.tier = tier;
242	    h.rank = i + 1;
243	  });
244	
245	  return { heroes, sorted };
246	}
247	
248	// ============================================================
249	// 数据加载 + 计算调度
250	// ============================================================
251	async function loadGameData() {
252	  const base = gameConfig.gameId === "lolm" ? "lolm" : "曙光英雄";
253	
254	  if (gameConfig.hasLanes) {
255	    // LOLM: 加载所有分路 JSON
256	    const results = await Promise.all(
257	      gameConfig.lanes.map(async lane => {
258	        const resp = await fetch(base + "/" + lane.dataFile);
259	        if (!resp.ok) throw new Error(`加载 ${lane.dataFile} 失败: ${resp.status}`);
260	        return [lane.name, await resp.json()];
261	      })
262	    );
263	    const rawData = Object.fromEntries(results);
264	    const data = computeLOLM(rawData);
265	
266	    // 转换为标准格式
267	    gameData = {
268	      hasLanes: true,
269	      lanes: {},
270	      allHeroes: data.allHeroes,
271	      globalZ: data.globalZ,
272	      globalSimple: data.globalSimple
273	    };
274	    for (const [name, heroes] of Object.entries(data.lanes)) {
275	      gameData.lanes[name] = heroes;
276	    }
277	  } else {
278	    // 曙光：加载单个 JSON
279	    const resp = await fetch(base + "/" + gameConfig.dataFile);
280	    if (!resp.ok) throw new Error(`加载数据失败: ${resp.status}`);
281	    const rawData = await resp.json();
282	    const data = computeSG(rawData);
283	    gameData = {
284	      hasLanes: false,
285	      heroes: data.heroes,
286	      sorted: data.sorted
287	    };
288	  }
289	}
290	
291	// ============================================================
292	// 获取当前有效的字段
293	// ============================================================
294	function getScoreField(hero) {
295	  if (gameConfig.hasLanes) {
296	    return currentMethod === "zscore" ? "score_zscore" : "score_simple";
297	  }
298	  return "score";
299	}
300	
301	function getTierField(hero) {
302	  if (gameConfig.hasLanes) {
303	    return currentMethod === "zscore" ? "tier_zscore" : "tier_simple";
304	  }
305	  return "tier";
306	}
307	
308	function getGlobalRank(hero) {
309	  if (gameConfig.hasLanes) {
310	    return hero[currentMethod === "zscore" ? "global_rank_zscore" : "global_rank_simple"];
