581	function sortTable(th, colIdx) {
582	  const table = th.closest("table");
583	  const tbody = table.querySelector("tbody");
584	  const rows = Array.from(tbody.querySelectorAll("tr"));
585	  const isDesc = th.classList.contains("sorted") && !th.classList.contains("desc");
586	
587	  table.querySelectorAll("th").forEach(h => { h.classList.remove("sorted", "desc"); });
588	  th.classList.add("sorted");
589	  if (isDesc) th.classList.add("desc");
590	
591	  // Determine which heroes list is active
592	  let heroes;
593	  if (gameData.hasLanes) {
594	    if (currentView === "global") {
595	      heroes = currentMethod === "zscore" ? gameData.globalZ : gameData.globalSimple;
596	    } else {
597	      heroes = gameData.lanes[currentLane] || [];
598	    }
599	  } else {
600	    heroes = gameData.heroes;
601	  }
602	
603	  // Build column definitions
604	  let cols;
605	  if (gameData.hasLanes && currentView === "global") {
606	    cols = gameConfig.globalColumns;
607	  } else {
608	    cols = gameConfig.columns;
609	  }
610	
611	  // Handle lane-specific rank column
612	  const col = (colIdx < cols.length) ? cols[colIdx] : { field: "globalRank", type: "rank" };
613	
614	  // 动态找到英雄名列的索引（而非硬编码 cells[1]）
615	  const nameColIdx = cols.findIndex(c => c.field === "name");
616	  rows.sort((a, b) => {
617	    const heroA = heroes.find(h => h.name === a.cells[nameColIdx]?.textContent?.trim());
618	    const heroB = heroes.find(h => h.name === b.cells[nameColIdx]?.textContent?.trim());
619	    const va = heroA ? (col.field === "laneRank" ? heroA.laneRank : heroA[col.field]) : 0;
620	    const vb = heroB ? (col.field === "laneRank" ? heroB.laneRank : heroB[col.field]) : 0;
621	
622	    if (col.type === "tier") {
623	      const order = ["T0", "T0.5", "T1", "T2", "T3", "T4"];
624	      const ia = order.indexOf(va), ib = order.indexOf(vb);
625	      return isDesc ? ib - ia : ia - ib;
626	    }
627	    const na = parseFloat(va), nb = parseFloat(vb);
628	    if (!isNaN(na) && !isNaN(nb)) {
629	      return isDesc ? nb - na : na - nb;
630	    }
631	    const sa = String(va != null ? va : ""), sb = String(vb != null ? vb : "");
632	    return isDesc ? sb.localeCompare(sa) : sa.localeCompare(sb);
633	  });
634	
635	  rows.forEach(r => tbody.appendChild(r));
636	}
